#!/usr/bin/env bash
# Expands the full OwO Farm tree into the current directory.
set -euo pipefail
cd "$(dirname "$0")"

python3 - << 'PY'
import base64, tarfile, io, os

B64 = r''''''

raw = base64.b64decode(B64)
buf = io.BytesIO(raw)
with tarfile.open(fileobj=buf, mode="r:gz") as tar:
    tar.extractall(".")
print("OK: repo files extracted")
for root, dirs, files in os.walk("."):
    # skip .git
    if ".git" in root:
        continue
    level = root.count(os.sep)
    if level > 3:
        continue
    for f in files:
        print(os.path.join(root, f))
PY
